import{z as n,x as o,o as E,c as d,q as s,j as l,D as e,d as r,s as i,S as B,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"进位选择","description":"","frontmatter":{"title":"进位选择","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/carry-select.md","filePath":"cs/carry-select.md","lastUpdated":1791063341000}'),p={name:"cs/carry-select.md"};function D(c,a,C,h,m,u){const A=o("Mermaid");return E(),d("div",null,[a[2]||(a[2]=s('<h1 id="进位选择" tabindex="-1">进位选择 <a class="header-anchor" href="#进位选择" aria-label="Permalink to &quot;进位选择&quot;">​</a></h1><div class="epigraph"><p>低位块还在算进位时，高位块先按进位入是 0 和 1 各加一遍，真正的进位到达只选一路。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/ripple-adder">行波进位对照</a>钉死了 RCA 的线性链。<a href="/cs/adder-cla">CLA</a>用 \\(g,p\\) 换深度。本课不重写组生成公式，也不从华莱士树另起。缺口是中间方案：<strong>进位选择</strong>——用面积买掉「等低位进位」的那段空闲。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把 \\(n\\) 位切成若干块。每块内部仍可用 RCA 或小 CLA。缺口是：块 \\(k\\) 的进位入要等块 \\(k-1\\) 算完。预先做两份：假设进位入为 0 的和与进位出，假设为 1 的另一份；低位进位到达后用 MUX 选。MUX 延迟换成两套加法器。</p><p>块等长时，总延迟大约是一块 RCA 加若干级 MUX，优于纯行波，通常仍不如宽 CLA 树。本课只钉这一种折中。</p><h3 id="选择不是超前" tabindex="-1">选择不是超前 <a class="header-anchor" href="#选择不是超前" aria-label="Permalink to &quot;选择不是超前&quot;">​</a></h3><p>CLA 在进位到达前就用 \\(g,p\\) 组合出正确进位。进位选择是<strong>猜两种、再选</strong>，进位值本身仍来自低位块，只是高位数据和已算好。把 carry-select 叫成 lookahead 的别名，后课分组 CLA 的 \\(G,P\\) 会混。</p><p><span class="marginnote">Harris 用不等长块减小 MUX 链上的空等。本课用等长块讲清结构即可。Patterson/Hennessy 不强制 CPU 用哪一种加法器。</span></p><p><span class="marginnote">直觉类比：像在路口两边各派一辆车提前出发——一辆假设绿灯、一辆假设红灯；信号灯真变的那一刻，扔掉开错方向的那辆。多花一辆车（面积），省下原地等灯的时间（延迟）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>例如 16 位：低 8 位 RCA，高 8 位两套 RCA + 8 位 MUX。进位出同样二选一，接到下一块。关键路径：第一块行波 + 后续 MUX。面积近乎 \\(1.5\\times\\)–\\(2\\times\\) 单套加法器（视块数）。</p><p><span class="marginnote">数字实例：16 位纯行波要串 16 个全加器；拆成低 8 位加高 8 位两套的进位选择后，关键路径约是低块 8 级全加器加一级 MUX——高位原本要等的 8 级，被「猜 0 和猜 1」的两套预加提前吃掉了。</span></p>',13)),(E(),l(B,null,{default:e(()=>[i(A,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20LO%5B%22%E4%BD%8E%E4%BD%8D%E5%9D%97%E7%AE%97%E5%87%BA%20c%22%5D%20--%3E%20MUX%5B%22MUX%20%E9%80%89%E9%AB%98%E4%BD%8D%E9%A2%84%E5%8A%A0%E7%BB%93%E6%9E%9C%22%5D%0A%20%20HI0%5B%22%E9%AB%98%E4%BD%8D%E5%81%87%E8%AE%BE%20c%3D0%22%5D%20--%3E%20MUX%0A%20%20HI1%5B%22%E9%AB%98%E4%BD%8D%E5%81%87%E8%AE%BE%20c%3D1%22%5D%20--%3E%20MUX%0A%20%20MUX%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E4%B9%98%E6%B3%95%E9%98%B5%E5%88%97%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"后课 ALU 仍是一个加减框；框内换 CSA 只改关键路径与面积，控制位不变。与 CLA 可混合：块内 CLA、块间选择。本课不把混合画完。",-1)),(E(),l(B,null,{default:e(()=>[i(A,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20RCA%5B%22%E7%BA%AF%20RCA%2016%20%E4%BD%8D%22%5D%20--%3E%20D1%5B%22%E5%BB%B6%E8%BF%9F%E7%BA%A6%2016%20%E7%BA%A7%E5%85%A8%E5%8A%A0%E5%99%A8%EF%BC%8C%E9%9D%A2%E7%A7%AF%E6%9C%80%E5%B0%8F%22%5D%0A%20%20CS%5B%22%E8%BF%9B%E4%BD%8D%E9%80%89%E6%8B%A9%EF%BC%9A%E4%B8%A4%E5%9D%97%208%20%E4%BD%8D%22%5D%20--%3E%20D2%5B%22%E5%BB%B6%E8%BF%9F%E7%BA%A6%208%20%E7%BA%A7%E5%8A%A0%20MUX%20%E9%93%BE%EF%BC%8C%E9%9D%A2%E7%A7%AF%E8%BF%91%E4%B8%A4%E5%80%8D%22%5D%0A%20%20CLA%5B%2216%20%E4%BD%8D%20CLA%20%E6%A0%91%22%5D%20--%3E%20D3%5B%22%E5%BB%B6%E8%BF%9F%E7%BA%A6%E5%AF%B9%E6%95%B0%E7%BA%A7%EF%BC%8C%E9%97%A8%E6%9C%80%E5%A4%9A%22%5D%0A%20%20D1%20--%3E%20T%5B%22%E4%B8%89%E6%A1%A3%E6%8A%98%E4%B8%AD%EF%BC%9A%E5%BB%B6%E8%BF%9F%E9%80%92%E5%87%8F%EF%BC%8C%E9%9D%A2%E7%A7%AF%E9%80%92%E5%A2%9E%22%5D%0A%20%20D2%20--%3E%20T%0A%20%20D3%20--%3E%20T%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p><span class="marginnote">常见误区：初学者容易以为「猜 0 和 1 各算一遍」最后还要校验哪个对——实际上两份结果都是完整正确的加法，真实进位到达时 MUX 只是二选一接线，不存在「算错重来」的惩罚。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲进位跳跃（bypass）、不把平方根块长优化写成作业。乘法的部分积压缩是下一课，不是进位选择的推广。</p><p>后课默认：加法器有 RCA / 选择 / CLA 三档延迟–面积；功能都是同一套全加。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>进位选择：高位两套预加，低位进位只做 MUX。</li><li>用面积换掉等待，不是 \\(g,p\\) 超前。</li><li>控制与溢出接线与上一课相同。</li><li>出处：Harris and Harris。</li></ul>',6))])}const F=n(p,[["render",D]]);export{f as __pageData,F as default};
